        $scope.CompareLabList = function (AddedLablist) {
            let differences = [];
            $scope.LogObj.LabList.forEach(function (editedItem) {

                var savedItem = AddedLablist.filter(function (item) {
                    return (item.ProcedureId === editedItem.ProcedureId) && (item.CheckListId == editedItem.CheckListId);
                }) || [];

                if (savedItem.length > 0) {
                    if ((savedItem) && (savedItem[0].ResultValue !== editedItem.ResultValue || savedItem[0].Normal == editedItem.Normal || savedItem[0].AbNormal == editedItem.AbNormal || savedItem[0].ResultId != editedItem.ResultId || savedItem[0].Remarks !== editedItem.Remarks)) {

                        differences.push({
                            ProcedureId: editedItem.ProcedureId,
                            savedResultValue: savedItem[0].ResultValue,
                            editedResultValue: editedItem.ResultValue
                        });
                    }
                }
            });

            return differences;

        }

        function generatePhysicalDescriptions(oldList, newList, oldNotes, newNotes) {
            let oldParts = [];
            let newParts = [];

            // Compare Dentition list
            newList.forEach(function (newItem) {
                let oldItem = oldList.find(item => item.Id === newItem.Id);
                if (!oldItem) {
                    newParts.push(newItem.Description);
                }
            });

            oldList.forEach(function (oldItem) {
                let newItem = newList.find(item => item.Id === oldItem.Id);
                if (!newItem) {
                    oldParts.push(oldItem.Description);
                }
            });

            // Compare Notes
            if ((oldNotes || '') !== (newNotes || '')) {
                if (oldNotes) oldParts.push(`Notes: ${oldNotes}`);
                if (newNotes) newParts.push(`Notes: ${newNotes}`);
            }

            return {
                oldDescription: oldParts.join(', '),
                newDescription: newParts.join(', ')
            };
        }
        function generateDentitionDescriptions(oldList, newList, oldNotes, newNotes) {
            let oldParts = [];
            let newParts = [];

            // Compare Dentition list
            newList.forEach(function (newItem) {
                let oldItem = oldList.find(item => item.DentitionId === newItem.DentitionId);
                if (!oldItem) {
                    newParts.push(newItem.DentitionName);
                }
            });

            oldList.forEach(function (oldItem) {
                let newItem = newList.find(item => item.DentitionId === oldItem.DentitionId);
                if (!newItem) {
                    oldParts.push(oldItem.DentitionName);
                }
            });

            // Compare Notes
            if ((oldNotes || '') !== (newNotes || '')) {
                if (oldNotes) oldParts.push(`Notes: ${oldNotes}`);
                if (newNotes) newParts.push(`Notes: ${newNotes}`);
            }

            return {
                oldDescription: oldParts.join(', '),
                newDescription: newParts.join(', ')
            };
        }


        function formatVitalsArray(array, indices, isAddCase, compareArray = []) {
            let result = "";

            indices.forEach(index => {
                const current = array[index];
                if (!current) return;

                const compare = compareArray.find((_, i) => i === index) || {};
                let vitalsString = "";

                const currentVitals = current.Vitals || [];
                const compareVitals = compare.Vitals || [];

                const isDeleted = current.DeleteInd === 'Y';

                // Compare individual vital values
                for (let i = 0; i < currentVitals.length; i++) {
                    const v = currentVitals[i] || {};
                    const c = compareVitals[i] || {};

                    const valueChanged = v.Value !== c.Value || v.UnitTypeId !== c.UnitTypeId;

                    if (isAddCase || valueChanged || isDeleted) {
                        if (v.Value !== undefined && v.Value !== null && v.Value !== "") {
                            vitalsString += `${v.VitalDesc}: ${v.Value}, `;
                        }
                    }
                }

                vitalsString = vitalsString.trim().replace(/,\s*$/, '');

                // Construct line
                let line = `(Vitals)V${index + 1}`;
                if (vitalsString) line += ` ${vitalsString}`;

                // Remarks
                if (isAddCase || current.VitalRemarks !== compare.VitalRemarks || isDeleted) {
                    if (current.VitalRemarks) {
                        line += ` | Remarks: ${current.VitalRemarks}`;
                    }
                }

                // Performed By
                if (isAddCase || current.DoctorId !== compare.DoctorId || isDeleted) {
                    if (current.DoctorId) {
                        line += ` | Performed By: ${current.UserName}`;
                    }
                }

                // Time
                if (isAddCase || current.VitalAddTime !== compare.VitalAddTime || isDeleted) {
                    if (current.VitalAddTime) {
                        line += ` | Time: ${current.VitalAddTime}`;
                    }
                }

                // If DeleteInd is 'Y', prefix "Deleted"
                if (isDeleted) {
                    line = `Deleted ${line}`;
                }

                // Only push if meaningful
                if (line !== `(Vitals)V${index + 1}`) {
                    result += line + '\n';
                }
            });

            return result.trim();
        }


        $scope.findHandPDifferences = function (savedArray, editedArray, LabsInvestigationsArray, editLabsInvestigationsArray) {
            var differences = [];
            /* var maxLength = Math.max(arr1.length, arr2.length);*/

            angular.forEach(savedArray, function (item) {
                //  item.ChecklistDate = item.ChecklistDate || null;
                item.Remarks = item.Remarks || '';

                var edited = editedArray.filter(function (eitem) {
                    //  eitem.ChecklistDate = eitem.ChecklistDate || null;
                    eitem.Remarks = eitem.Remarks || '';

                    return ((eitem.HistoryId == item.HistoryId) && (item.TypeId == eitem.TypeId) && (item.Value == eitem.Value) && (item.Remarks == eitem.Remarks) && (item.DeleteInd == eitem.DeleteInd));
                }) || [];


                if (edited.length == 0) {
                    differences.push({
                        HistoryId: item.HistoryId,
                        TypeId: item.TypeId,
                        HistoryName: item.HistoryName,
                        Value: item.Value,
                    });
                    /*count++;*/
                }

            });
            angular.forEach(LabsInvestigationsArray, function (item) {
                var edited = editLabsInvestigationsArray.filter(function (eitem) {

                    return ((eitem.ProcedureId == item.ProcedureId) && (item.ProcedureName == eitem.ProcedureName) && (item.ResultValue == eitem.ResultValue));
                }) || [];


                if (edited.length == 0) {
                    differences.push({
                        ProcedureId: item.ProcedureId,
                        ProcedureName: item.ProcedureName,
                        ResultValue: item.ResultValue,
                    });

                }

            });

            return differences;
        };

