        $scope.GetAllFrequentlyAddedData = function () {
            var allrgireq = {
                "HospitalId": $scope.HospitalId,
                "PageSize": 30,
                "PageNumber": 1,
                "UserId": doctorinfo.doctorid,
                "IsFrequent": "Y"

            };
            eHnoteDiagnosisDataServices.GetAllFrequentlyAddedData(allrgireq).then(function (resp) {

                if (resp.data.Status === "Success") {

                    $scope.FrequentlyAllergyitems = resp.data.Allergyitems || [];
                    $scope.FrequentMedicationsList = resp.data.OrganizationFavoriteMedications || [];

                    angular.forEach($scope.FrequentlyAllergyitems, function (item) {
                        item.IsChecked = false;
                    });

                    angular.forEach($scope.FrequentMedicationsList, function (item) {
                        item.IsChecked = false;
                    });

                    if ($scope.obj.AllergyItems.length > 0) {
                        angular.forEach($scope.obj.AllergyItems, function (item) {
                            if (item.DeleteInd == 'N') {
                                var FreqList = $filter("filter")($scope.FrequentlyAllergyitems, function (fitem) {
                                    return fitem.AllergyId == item.AllergyId;
                                }, true) || [];
                                if (FreqList.length > 0) {
                                    FreqList[0].Onselect = true;
                                }
                            }
                        });
                    }

                    if ($scope.obj.CurrentSystemicMedicationsHistory.length > 0) {
                        angular.forEach($scope.obj.CurrentSystemicMedicationsHistory, function (item) {
                            if (item.DeleteInd == 'N') {
                                var MedFreqList = $filter("filter")($scope.FrequentMedicationsList, function (fitem) {
                                    return fitem.MedicineId == item.MedicineId;
                                }, true) || [];
                                if (MedFreqList.length > 0) {
                                    MedFreqList[0].IsChecked = true;
                                }
                            }
                        });
                    }

                }
            })
        }

        $scope.OnClickNormalInChecklists = function (boolvalue, id) {
            id = id || null;
            if (id != null) {
                if (boolvalue) {
                    angular.forEach($scope.PreAdmAnesthetistObj.AllOrgAscChecklistData, function (item) {
                        if (item.CheckListCategoryId === id) {
                            if (item.IsNormal) {
                                item.IsChecked = true;
                            }
                            item.SubCheckList = item.SubCheckList || [];
                            if (item.SubCheckList.length > 0) {
                                angular.forEach(item.SubCheckList, function (kitem) {
                                    if (kitem.IsNormal) {
                                        kitem.IsChecked = true;
                                    }
                                });
                            }
                            if (item.IsNormal == null || item.IsNormal == false) {
                                if (item.IsChecked = true) {
                                    item.IsChecked = false;
                                }
                                item.SubCheckList = item.SubCheckList || [];
                                if (item.SubCheckList.length > 0) {
                                    angular.forEach(item.SubCheckList, function (kitem) {
                                        if (kitem.IsNormal == false || kitem.IsNormal == null) {
                                            if (kitem.IsChecked = true) {
                                                kitem.IsChecked = false;
                                            }
                                        }
                                    });
                                }
                            }

                        }
                    });
                } else {
                    angular.forEach($scope.PreAdmAnesthetistObj.AllOrgAscChecklistData, function (item) {
                        if (item.CheckListCategoryId === id) {
                            if (item.IsNormal) {
                                item.IsChecked = false;
                            }
                            item.SubCheckList = item.SubCheckList || [];
                            if (item.SubCheckList.length > 0) {
                                angular.forEach(item.SubCheckList, function (kitem) {
                                    if (kitem.IsNormal) {
                                        kitem.IsChecked = false;
                                    }
                                });
                            }
                        }
                    });
                }
            }
        };

        $scope.OnSelectMainChecklist = function (boolvalue, obj) {
            if (boolvalue) {
                if (obj.SubCheckList.length > 0) {
                    angular.forEach(obj.SubCheckList, function (kitem) {
                        kitem.IsChecked = true;
                    });
                }

            } else {
                if (obj.SubCheckList.length > 0) {
                    angular.forEach(obj.SubCheckList, function (kitem) {
                        kitem.IsChecked = false;
                    });
                }
            }

            CheckUncheckNormalCheckBox();
        };

        function CheckUncheckNormalCheckBox() {
            let counter = 0;
            let counter1 = 0;
            let counter11 = 0;
            let beforeAnesthesiaChecklistArray = $filter('filter')($scope.PreAdmAnesthetistObj.AllOrgAscChecklistData, { 'CheckListCategoryId': 7 }, true);
            angular.forEach(beforeAnesthesiaChecklistArray, function (item) {
                if (item.IsNormal) {
                    counter++;
                }
                if (item.IsChecked && item.IsNormal) {
                    counter1++;
                }
                if (item.IsChecked) {
                    counter11++;
                }
                if (item.SubCheckList.length > 0) {
                    angular.forEach(item.SubCheckList, function (kitem) {
                        if (kitem.IsNormal) {
                            counter++;
                        }
                        if (kitem.IsChecked && kitem.IsNormal) {
                            counter1++;
                        }
                        if (kitem.IsChecked) {
                            counter11++;
                        }
                    });
                }
            });

            if (counter == counter1 && counter1 == counter11) {
                $scope.PreAdmAnesthetistObj.IsBeforeAnesthesiaNormal = true;
            } else {
                $scope.PreAdmAnesthetistObj.IsBeforeAnesthesiaNormal = false;
            }
        };

        $scope.OnSelectSubChecklist = function (boolvalue, obj) {
            if (boolvalue) {
                obj.IsChecked = true;

            } else {
                let tempArray = $filter('filter')(obj.SubCheckList, { 'IsChecked': false }, true);
                if (tempArray.length == obj.SubCheckList.length) {
                    obj.IsChecked = false;
                }
            }

            // check,uncheck "Normal" checkbox case
            CheckUncheckNormalCheckBox();
        };

        $scope.ShowChecklistAddForm = function (val) {
            if (val === 7) {
                $scope.PreAdmAnesthetistObj.IsBeforeAnesthesiaAddForm = true;
            }
        };

        $scope.CloseChecklistAddForm = function (val) {
            $scope.PreAdmAnesthetistObj.MainChecklistName = "";
            if (val === 7) {
                $scope.PreAdmAnesthetistObj.IsBeforeAnesthesiaAddForm = false;
            }
        }

        $scope.AddNewIntraOpMainChecklist = function (val) {

            $scope.LogObj.LogArray = [];
            if ($scope.PreAdmAnesthetistObj.MainChecklistName === "") {
                alertify.error("Please enter checklist name!");
                return false;
            }

            let req = {
                "OrganizationPreOpCheckListId": 0,
                "ParentOrganizationId": $scope.ParenthospitalId,
                "UserId": $scope.UserId,
                "CheckListCategoryId": val,
                "CheckListId": 0,
                "CheckListModuleId": 2,
                "CheckListName": $scope.PreAdmAnesthetistObj.MainChecklistName,
                "CheckListSubTypeId": null,
                "OrganizationCheckListDetails": [],
                "DeleteInd": "N",
                "Logs": {},
            };

            $scope.PreAdmAnesthetistObj.MainChecklistName = $scope.PreAdmAnesthetistObj.MainChecklistName || '';
            if ($scope.PreAdmAnesthetistObj.MainChecklistName != '') {
                let ActionDescription = '';

                if (val == 7) {
                    ActionDescription = `New Item for Before Anesthesia in Pre-Op Anesthesia for Appointment ID: ${$scope.cacheStorageItem.AppointmentId}`;
                }

                let obj = {
                    "LogId": 0,
                    "ModuleId": 2,
                    "ModuleName": "ASC",
                    "SubModuleId": 9,
                    "SubModuleName": "Pre-Op",
                    "ScreenType": "Pre-Op Anesthesia (Before Anesthesia)",
                    "ActionType": "Added",
                    "ActionDescription": ActionDescription,
                    "ActionDateTime": $filter("date")(new Date(), "yyyy-MM-dd HH:mm:ss"),
                };
                $scope.LogObj.LogArray.push(obj);
            }

            if ($scope.LogObj.LogArray.length > 0) {
                req.Logs = $scope.LogObj || {};
            }
            eHnoteSurgeryService.AddUpdateOrganizationPreOpCheckListData(req).then(function (resp) {
                if (resp.data.status === "Success") {
                    alertify.success("Checklist added successfully!");
                    $scope.init();
                }
                if (resp.data.status === "Failure") {
                    alertify.error(resp.data.Message);
                }
            }, function (err) {
                console.log(err);
            });
            $scope.CloseChecklistAddForm(val);
        };

